package app.dayflow.assistant;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import androidx.core.content.FileProvider;import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
/** Explicitly enabled localhost bridge. Two workers and finite request queue, no background polling. */
public final class ApiService extends Service {
 private volatile ServerSocket server;private volatile String token="";private final ExecutorService acceptor=Executors.newSingleThreadExecutor();private final ThreadPoolExecutor clients=new ThreadPoolExecutor(2,2,20,TimeUnit.SECONDS,new ArrayBlockingQueue<>(4),new ThreadPoolExecutor.AbortPolicy());private final Set<Socket> sockets=java.util.concurrent.ConcurrentHashMap.newKeySet();
 public android.os.IBinder onBind(Intent i){return null;}public int onStartCommand(Intent intent,int flags,int id){if(intent==null||intent.getStringExtra("token")==null){stopSelf();return START_NOT_STICKY;}if(server!=null)return START_NOT_STICKY;token=intent.getStringExtra("token");NotificationManager manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("assistant_api","本机助手API",NotificationManager.IMPORTANCE_LOW));PendingIntent stop=PendingIntent.getBroadcast(this,0,new Intent(this,StopReceiver.class),PendingIntent.FLAG_IMMUTABLE);startForeground(8766,new Notification.Builder(this,"assistant_api").setSmallIcon(android.R.drawable.ic_menu_share).setContentTitle("日栖本机API已开启").setContentText("127.0.0.1:8766 · 仅授权密钥访问").addAction(new Notification.Action.Builder(null,"停止",stop).build()).setOngoing(true).build());acceptor.execute(()->{try{ServerSocket listener=new ServerSocket();listener.bind(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),8766));server=listener;while(!listener.isClosed()){Socket socket=listener.accept();socket.setSoTimeout(30000);sockets.add(socket);try{clients.execute(()->serve(socket));}catch(RejectedExecutionException e){sockets.remove(socket);socket.close();}}}catch(Exception e){stopSelf();}});return START_NOT_STICKY;}
 private String line(InputStream input)throws IOException{ByteArrayOutputStream line=new ByteArrayOutputStream();int next;while((next=input.read())!=-1){if(next=='\n')break;if(line.size()>8192)throw new IOException("请求头过长");if(next!='\r')line.write(next);}return line.toString(StandardCharsets.ISO_8859_1.name());}
 private void serve(Socket socket){File inputFile=null;Uri shared=null;try{BufferedInputStream input=new BufferedInputStream(socket.getInputStream());String[] first=line(input).split(" ",3);if(first.length!=3)throw new IOException("无效请求");Map<String,String> headers=new HashMap<>();for(int n=0;n<64;n++){String line=line(input);if(line.isEmpty())break;int colon=line.indexOf(':');if(colon<=0)throw new IOException("无效请求头");headers.put(line.substring(0,colon).toLowerCase(Locale.ROOT),line.substring(colon+1).trim());if(n==63)throw new IOException("请求头过多");}String auth=headers.getOrDefault("authorization","");String supplied=auth.startsWith("Bearer ")?auth.substring(7):"";if(token.isEmpty()||!java.security.MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),supplied.getBytes(StandardCharsets.UTF_8))){respond(socket,401,new JSONObject().put("error","未授权"));return;}if(first[0].equals("GET")&&first[1].equals("/openapi.json")){try(InputStream spec=getAssets().open("openapi.json")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int count;while((count=spec.read(buffer))!=-1)bytes.write(buffer,0,count);respond(socket,200,new JSONObject(bytes.toString("UTF-8")));return;}}String path=first[1].split("\\?",2)[0];String method;switch(path){case "/v1/capabilities":method="capabilities";break;case "/v1/today":method="today";break;case "/v1/notes/search":method="search_notes";break;case "/v1/capture":method="capture";break;case "/v1/notes":method="create_note";break;case "/v1/tasks":method="create_task";break;case "/v1/tasks/complete":method="complete_task";break;default:respond(socket,404,new JSONObject().put("error","接口不存在"));return;}boolean read=method.equals("capabilities")||method.equals("today")||method.equals("search_notes");if(!first[0].equals(read?"GET":"POST")){respond(socket,405,new JSONObject().put("error","请求方法不匹配"));return;}JSONObject args=new JSONObject();if(!read){if(headers.containsKey("transfer-encoding"))throw new IOException("请发送Content-Length");long remaining=Long.parseLong(headers.getOrDefault("content-length","0"));if(remaining<=0)throw new IOException("需要JSON请求体");StringBuilder text=new StringBuilder();Reader reader=new InputStreamReader(new FilterInputStream(input){long left=remaining;public int read()throws IOException{if(left<=0)return -1;int value=super.read();if(value!=-1)left--;return value;}public int read(byte[] bytes,int offset,int count)throws IOException{if(left<=0)return -1;int value=super.read(bytes,offset,(int)Math.min(left,count));if(value!=-1)left-=value;return value;}},StandardCharsets.UTF_8);char[] buffer=new char[8192];int n;while((n=reader.read(buffer))!=-1)text.append(buffer,0,n);args=new JSONObject(text.toString());}else{Uri query=Uri.parse("http://127.0.0.1"+first[1]);for(String key:query.getQueryParameterNames())args.put(key,query.getQueryParameter(key));}if(args.has("content_uri"))throw new IOException("外部请求不能指定内部文件URI");if(args.optString("content").length()>16000){File dir=new File(getCacheDir(),"api-input");dir.mkdirs();inputFile=File.createTempFile("input-",".md",dir);try(Writer out=new OutputStreamWriter(new FileOutputStream(inputFile),StandardCharsets.UTF_8)){out.write(args.getString("content"));}shared=FileProvider.getUriForFile(this,"app.dayflow.assistant.files",inputFile);grantUriPermission("app.dayflow",shared,Intent.FLAG_GRANT_READ_URI_PERMISSION);args.remove("content");args.put("content_uri",shared.toString());}Bundle request=new Bundle();request.putString("token",token);request.putString("json",args.toString());Bundle result=getContentResolver().call(Uri.parse("content://app.dayflow.api"),method,null,request);if(result==null)throw new IOException("主应用未响应");int status=result.getInt("status",500);respond(socket,status,status==200?new JSONObject(result.getString("json","{}")):new JSONObject().put("error",result.getString("error","请求失败")));}catch(Exception ignored){try{if(!socket.isClosed())respond(socket,400,new JSONObject().put("error","请求失败，请核对格式及主应用API设置"));}catch(Exception none){}}finally{try{socket.close();}catch(Exception ignored){}sockets.remove(socket);if(shared!=null)revokeUriPermission("app.dayflow",shared,Intent.FLAG_GRANT_READ_URI_PERMISSION);if(inputFile!=null)inputFile.delete();}}
 private void respond(Socket socket,int code,JSONObject value)throws IOException{byte[] bytes=value.toString().getBytes(StandardCharsets.UTF_8);OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 "+code+" "+(code==200?"OK":"Error")+"\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: "+bytes.length+"\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(bytes);out.flush();}
 public void onDestroy(){token="";try{if(server!=null)server.close();}catch(Exception ignored){}for(Socket socket:sockets)try{socket.close();}catch(Exception ignored){}acceptor.shutdownNow();clients.shutdownNow();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
